(()=>{
  const game=document.getElementById('forestGame');if(!game)return;
  const spots=[...game.querySelectorAll('[data-discovery]')],cab=game.querySelector('#forestCabin'),count=game.querySelector('#forestCount'),pips=[...game.querySelectorAll('.forest-pips i')],narration=game.querySelector('#forestNarration'),walk=game.querySelector('#forestWalk'),room=game.querySelector('#forestRoom');
  const discoveries={cedar:'The ancient cedar has stood here longer than anyone remembers. Rest your hand on the moss; the woods are asking you to slow down.',light:'A warm lantern flickers among the ferns. Somebody left a light on for you. The cabin feels a little closer now.',path:'The rain-washed boards curve gently into the trees. You follow them toward the promise of warmth and quiet.'};
  const discoveryPhotos={
    cedar:{image:'/assets/moss-cedar-detail.webp',alt:'Close-up of an ancient cedar tree wrapped in deep green moss and delicate ferns',title:'The ancient cedar',chapter:'01 / A LIVING LANDMARK',description:'Look closer. Generations of rain have softened this enormous cedar in a green velvet coat. Every little fern growing in its bark is a reminder that the forest is always making room for new life.'},
    light:{image:'/assets/moss-lantern-detail.webp',alt:'A small amber lantern casting a warm glow across damp planks and mossy ferns',title:'A little light',chapter:'02 / THE WELCOME LANTERN',description:'A single lantern glows beside the path, its warmth reflected in the rain. Someone has left a light for you. Beyond the ferns, the forest cabin is beginning to feel like home.'},
    path:{image:'/assets/moss-path-detail.webp',alt:'Rain-washed wooden walkway winding through the mist toward a glowing cabin',title:'The wooden walkway',chapter:'03 / THE WAY FORWARD',description:'Follow the quiet rhythm of the rain-washed boards. The path curves between towering trees toward a golden glow. Every step takes you farther from the rush of ordinary life.'},
    cabin:{image:'/assets/moss-forest-walkway.webp',alt:'Warmly illuminated cedar cabin peeking through the trees at the end of the walkway',title:'The Stillwater Cabin',chapter:'YOUR DESTINATION / HOME IN THE WOODS',description:'There it is: a cedar-and-glass retreat tucked into the forest, with a fire waiting inside and nothing on the schedule but rest. A little world where you can finally exhale.'}
  };
  const modal=game.querySelector('#forestDiscoveryModal'),modalPhoto=game.querySelector('#forestDiscoveryImage'),modalTitle=game.querySelector('#forestDiscoveryTitle'),modalText=game.querySelector('#forestDiscoveryDescription'),modalChapter=game.querySelector('#forestDiscoveryChapter'),modalContinue=game.querySelector('#forestDiscoveryContinue'),modalCount=game.querySelector('#forestDiscoveryCount');let lastFocus=null,modalKind=null;
  const closePhoto=()=>{if(modal.hidden)return;modal.hidden=true;game.classList.remove('photo-open');lastFocus?.focus({preventScroll:true})};
  const openPhoto=(kind,trigger)=>{const details=discoveryPhotos[kind];lastFocus=trigger;modalKind=kind;modalPhoto.src=details.image;modalPhoto.alt=details.alt;modalTitle.textContent=details.title;modalText.textContent=details.description;modalChapter.textContent=details.chapter;modalCount.textContent=kind==='cabin'?(found.size===3?'THE CABIN IS OPEN':'FIND '+(3-found.size)+' MORE DISCOVERIES'):String(found.size).padStart(2,'0')+' / 03 DISCOVERED';modalContinue.textContent=kind==='cabin'&&found.size===3?'ENTER THE CABIN ↗':'CONTINUE EXPLORING ↗';modal.hidden=false;game.classList.add('photo-open');modalContinue.focus({preventScroll:true})};
  modalContinue.addEventListener('click',()=>{const toEnter=modalKind==='cabin'&&found.size===3;closePhoto();if(toEnter)enter()});
  game.querySelector('#forestDiscoveryClose').addEventListener('click',closePhoto);
  game.querySelector('#forestDiscoveryBackdrop').addEventListener('click',closePhoto);
  modal.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();closePhoto()}if(e.key==='Tab'){const focusable=[game.querySelector('#forestDiscoveryClose'),modalContinue];if(e.shiftKey&&document.activeElement===focusable[0]){e.preventDefault();focusable[1].focus()}else if(!e.shiftKey&&document.activeElement===focusable[1]){e.preventDefault();focusable[0].focus()}}});
  const found=new Set();let started=false;
  const say=s=>{narration.textContent=s};
  const update=()=>{count.textContent=String(found.size).padStart(2,'0')+' / 03';pips.forEach((pip,i)=>pip.classList.toggle('complete',i<found.size));if(found.size===3){cab.classList.add('ready');walk.innerHTML='ENTER THE CABIN <span>↗</span>';say('The path is clear. You can see firelight through the windows. The cabin is waiting—go on in.')}};
  const discover=spot=>{const id=spot.dataset.discovery;if(!found.has(id)){found.add(id);spot.classList.add('discovered');spot.setAttribute('aria-label',spot.getAttribute('aria-label')+' — discovered')}say(discoveries[id]);update();openPhoto(id,spot)};
  const enter=()=>{if(found.size<3){say('The cabin glows just beyond the trees. Find '+(3-found.size)+' more forest '+(3-found.size===1?'discovery':'discoveries')+' to make your way inside.');return}game.classList.add('inside');room.hidden=false;game.querySelector('#forestReturn').focus({preventScroll:true})};
  const reset=()=>{closePhoto();game.classList.remove('inside');room.hidden=true;found.clear();spots.forEach(s=>s.classList.remove('discovered'));cab.classList.remove('ready');walk.innerHTML='BEGIN EXPLORING <span>↗</span>';say('The forest is quiet, but never empty. Touch the glowing markers to discover three little moments on your way to the cabin.');started=false;update();game.scrollIntoView({behavior:'smooth',block:'start'})};
  spots.forEach(s=>s.addEventListener('click',()=>discover(s)));
  cab.addEventListener('click',()=>{if(found.size<3)say('The cabin is waiting. Discover the three moments in the forest to unlock the door.');openPhoto('cabin',cab)});
  walk.addEventListener('click',()=>{if(found.size===3){enter();return}if(!started){started=true;say('The walkway is beneath your feet. Follow the little glowing markers through the forest; there are three discoveries to find.');walk.innerHTML='EXPLORE THE MARKERS <span>✦</span>'}else{const missing=spots.find(s=>!found.has(s.dataset.discovery));if(missing){missing.focus({preventScroll:true});say('Look for a soft glow nearby. Every little discovery brings you closer to the cabin.')}}});
  game.querySelector('#forestReturn').addEventListener('click',()=>{game.classList.remove('inside');room.hidden=true;say('Back among the trees. The cabin light will still be here whenever you need it.')});
  game.querySelector('#forestRestart').addEventListener('click',reset);
  if(matchMedia('(pointer:fine) and (prefers-reduced-motion:no-preference)').matches){game.addEventListener('pointermove',e=>{const b=game.getBoundingClientRect();if(e.clientY<b.top||e.clientY>b.bottom)return;game.style.setProperty('--move-x',((e.clientX-b.left)/b.width-.5)*-15+'px');game.style.setProperty('--move-y',((e.clientY-b.top)/b.height-.5)*-11+'px')});game.addEventListener('pointerleave',()=>{game.style.setProperty('--move-x','0px');game.style.setProperty('--move-y','0px')})}
})();
